// Uma função async devolve sempre uma Promise
async function saudacao() {
  return "Olá";
}

saudacao().then(valor => console.log(valor)); // "Olá"

async function carregarDados(url) {
  try {
    const resposta = await fetch(url);

    if (!resposta.ok) {
      throw new Error(`Erro HTTP: ${resposta.status}`);
    }

    const dados = await resposta.json();
    return dados;
  } catch (erro) {
    console.error("Falha ao carregar dados:", erro.message);
    throw erro; // relança para quem chamou decidir o que fazer
  } finally {
    console.log("Pedido terminado");
  }
}

function esperar(ms, valor) {
  return new Promise(resolve => setTimeout(() => resolve(valor), ms));
}

async function emSerie() {
  console.time("serie");
  const a = await esperar(1000, "A"); // espera 1000ms
  const b = await esperar(1000, "B"); // só arranca depois do anterior acabar
  console.timeEnd("serie"); // aproximadamente 2000ms
  return [a, b];
}

function esperar(ms, valor) {
  return new Promise(resolve => setTimeout(() => resolve(valor), ms));
}

async function emParalelo() {
  console.time("paralelo");
  const [a, b] = await Promise.all([
    esperar(1000, "A"),
    esperar(1000, "B"),
  ]);
  console.timeEnd("paralelo"); // aproximadamente 1000ms
  return [a, b];
}

