exercises.statement:
Tens o código seguinte, que usa .then/.catch:

function obterNumero() {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      const numero = Math.random();
      if (numero < 0.5) {
        reject(new Error("Número demasiado baixo"));
      } else {
        resolve(numero);
      }
    }, 500);
  });
}

function mostrarNumero() {
  obterNumero()
    .then(numero => console.log("Número:", numero))
    .catch(erro => console.error("Erro:", erro.message));
}

Reescreve a função mostrarNumero usando async/await e try/catch, mantendo exatamente o mesmo comportamento (mesma mensagem em caso de sucesso, mesma mensagem em caso de erro). A função obterNumero não deve ser alterada.

exercises.solution_code:
function obterNumero() {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      const numero = Math.random();
      if (numero < 0.5) {
        reject(new Error("Número demasiado baixo"));
      } else {
        resolve(numero);
      }
    }, 500);
  });
}

async function mostrarNumero() {
  try {
    const numero = await obterNumero();
    console.log("Número:", numero);
  } catch (erro) {
    console.error("Erro:", erro.message);
  }
}

mostrarNumero();

exercises.statement:
Tens duas funções auxiliares, independentes uma da outra:

function obterUtilizador() {
  return new Promise(resolve => setTimeout(() => resolve({ id: 1, nome: "Ana" }), 800));
}

function obterPosts() {
  return new Promise(resolve => setTimeout(() => resolve(["Post 1", "Post 2"]), 800));
}

Escreve uma função async chamada carregarPagina que obtenha o utilizador e os posts em paralelo (não em série), e devolva um objeto { utilizador, posts }. O tempo total de execução deve rondar os 800ms, e não os 1600ms que resultariam de esperar por cada um separadamente.

exercises.solution_code:
function obterUtilizador() {
  return new Promise(resolve => setTimeout(() => resolve({ id: 1, nome: "Ana" }), 800));
}

function obterPosts() {
  return new Promise(resolve => setTimeout(() => resolve(["Post 1", "Post 2"]), 800));
}

async function carregarPagina() {
  const [utilizador, posts] = await Promise.all([
    obterUtilizador(),
    obterPosts(),
  ]);
  return { utilizador, posts };
}

carregarPagina().then(pagina => console.log(pagina));

exercises.statement:
O código abaixo tem três problemas relacionados com async/await: (1) na função registarProduto falta um await, o que faz com que preco seja uma Promise em vez de um número, provocando um erro ao chamar preco.toFixed(2); (2) na função calcularTotal há uma mistura desnecessária de .then com await; (3) em calcularTotal, obterPreco e obterImposto são independentes mas estão a ser esperados em série, desperdiçando tempo. Corrige os três problemas, mantendo o resultado final igual.

function obterPreco(produtoId) {
  return new Promise(resolve => setTimeout(() => resolve(10 + produtoId), 400));
}

function obterImposto(produtoId) {
  return new Promise(resolve => setTimeout(() => resolve(produtoId * 0.1), 400));
}

async function registarProduto(produtoId) {
  const preco = obterPreco(produtoId);
  console.log(`A registar produto com preço ${preco.toFixed(2)}`);
}

async function calcularTotal(produtoId) {
  const preco = await obterPreco(produtoId).then(p => p);
  const imposto = await obterImposto(produtoId);
  return preco + imposto;
}

